    try:
        with Image.open(image_path) as img:
            return imagehash.average_hash(img)
    except Exception as e:
        print(f"Error processing image {image_path}: {e}")
        return None

def find_duplicate_images(directory):
    hashes = {}
    duplicates = []

    for root, _, files in os.walk(directory):
        for file in files:
            if file.lower().endswith(('png', 'jpg', 'jpeg', 'bmp', 'gif', 'tiff')):
                file_path = os.path.join(root, file)
                file_size = os.path.getsize(file_path)
                img_hash = get_image_hash(file_path)

                if img_hash is not None:
                    hash_key = (img_hash, file_size)

                    if hash_key in hashes:
                        duplicates.append((file_path, hashes[hash_key]))
                    else:
                        hashes[hash_key] = file_path

    return duplicates

def remove_or_move_duplicates(duplicates, move_folder=None):
    if move_folder and not os.path.exists(move_folder):
        os.makedirs(move_folder)

    for duplicate, original in duplicates:
        if move_folder:
            try:
                shutil.move(duplicate, move_folder)
                print(f"Moved {duplicate} to {move_folder}")
            except Exception as e:
                print(f"Error moving file {duplicate}: {e}")
