```java
public class ArrayQueue<T> {
    private T[] queue;
    private int front;
    private int rear;
    private int size;
    private int maxSize;

    @SuppressWarnings("unchecked")
    public ArrayQueue(int maxSize) {
        this.maxSize = maxSize;
        this.queue = (T[]) new Object[maxSize];
        this.front = 0;
        this.rear = 0;
        this.size = 0;
    }

    public void enqueue(T element) throws IllegalStateException {
        if (size == maxSize) {
            throw new IllegalStateException("Queue is full");
        }
        queue[rear] = element;
        rear = (rear + 1) % maxSize;
        size++;
    }

    public T dequeue() {
        if (isEmpty()) {
            return null;
        }
        T element = queue[front];
        queue[front] = null; // Optional: Clear the reference to help garbage collection
        front = (front + 1) % maxSize;
        size--;
        return element;
    }

    public boolean isEmpty() {
        return size == 0;
    }

    public int getSize() {
        return size;
    }

    public int getMaxSize() {
        return maxSize;
    }

    public static void main(String[] args) {
        ArrayQueue<Integer> queue = new ArrayQueue<>(5);

        // Enqueue elements
        try {
            queue.enqueue(1);
            queue.enqueue(2);
            queue.enqueue(3);
            queue.enqueue(4);
            queue.enqueue(5);
            // This will throw an exception
            queue.enqueue(6);
        } catch (IllegalStateException e) {
            System.out.println(e.getMessage());
        }

        // Dequeue elements
        System.out.println("Dequeued: " + queue.dequeue());
        System.out.println("Dequeued: " + queue.dequeue());

        // Check if queue is empty
        System.out.println("Is queue empty? " + queue.isEmpty());

        // Get size of the queue
        System.out.println("Current size of queue: " + queue.getSize());
    }
}
```

