    // Method to sort an array using Counting Sort algorithm
    public static void countingSort(int[] array) {
        // Find the maximum value in the array to determine the range of the count array
        int max = findMax(array);

        // Create a count array to store the count of each unique integer
        int[] count = new int[max + 1];

        // Store the count of each integer in the count array
        for (int num : array) {
            count[num]++;
        }

        // Reconstruct the sorted array using the count array
        int index = 0;
        for (int i = 0; i < count.length; i++) {
            while (count[i] > 0) {
                array[index++] = i;
                count[i]--;
            }
        }
    }

    // Helper method to find the maximum value in an array
    private static int findMax(int[] array) {
        int max = array[0];
        for (int num : array) {
            if (num > max) {
                max = num;
            }
        }
        return max;
    }

