```cpp
#include <iostream>
#include <vector>
#include <string>
#include <algorithm>

std::string longestCommonSubstring(const std::string &s1, const std::string &s2) {
    int m = s1.length();
    int n = s2.length();

    // Create a 2D table to store lengths of longest common suffixes
    // of substrings. LCSuff[i][j] will be the length of longest common
    // suffix of s1[0..i-1] and s2[0..j-1].
    std::vector<std::vector<int>> LCSuff(m + 1, std::vector<int>(n + 1, 0));

    int length = 0; // To store length of the longest common substring
    int endIndex = 0; // To store the ending index of the longest common substring in s1

    // Building the LCSuff table and finding the longest common substring
    for (int i = 1; i <= m; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (s1[i - 1] == s2[j - 1]) {
                LCSuff[i][j] = LCSuff[i - 1][j - 1] + 1;

                // Update length and endIndex if a longer common substring is found
                if (LCSuff[i][j] > length) {
                    length = LCSuff[i][j];
                    endIndex = i;
                }
            } else {
                LCSuff[i][j] = 0;
            }
        }
    }

    // If no common substring is found, return an empty string
    if (length == 0) {
        return "";
    }

    // The longest common substring
    return s1.substr(endIndex - length, length);
}

int main() {
    std::string s1 = "ABABC";
    std::string s2 = "BABCAB";

    std::string result = longestCommonSubstring(s1, s2);
