import java.util.InputMismatchException;
import java.util.Random;
import java.util.Scanner;

public class RandomNumberGenerator {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int lowerBound = 0;
        int upperBound = 0;
        boolean validInput = false;

        // Prompt the user for the range until valid input is provided
        while (!validInput) {
            try {
                // Get the lower bound from the user
                System.out.print("Enter the lower bound of the range: ");
                lowerBound = scanner.nextInt();

                // Get the upper bound from the user
                System.out.print("Enter the upper bound of the range: ");
                upperBound = scanner.nextInt();

                // Check if the range is valid
                if (lowerBound >= upperBound) {
                    System.out.println("Invalid range. The lower bound should be less than the upper bound.");
                } else {
                    validInput = true; // Valid input received
                }
            } catch (InputMismatchException e) {
                // Handle non-integer input
                System.out.println("Invalid input. Please enter valid integers for the range.");
                scanner.next(); // Clear the invalid input
            }
        }

        // Generate a random number within the specified range
        int randomNumber = generateRandomNumber(lowerBound, upperBound);

        // Display the generated random number to the user
        System.out.println("Random number generated within the range [" + lowerBound + ", " + upperBound + "]: " + randomNumber);

        // Close the scanner
        scanner.close();
    }

    /**
     * Generates a random number within the given range.
     *
     * @param lowerBound The lower bound of the range (inclusive).
     * @param upperBound The upper bound of the range (inclusive).
     * @return A random number within the specified range.
     */
    private static int generateRandomNumber(int lowerBound, int upperBound) {
        Random random = new Random();
        return random.nextInt((upperBound - lowerBound) + 1) + lowerBound;
    }
}
