   -- Procedure to swap two integer variables using the XOR swap algorithm
   procedure Swap_Using_XOR (X, Y : in out Integer) is
   begin
      -- XOR swap step 1: X := X XOR Y
      X := X xor Y;

      -- XOR swap step 2: Y := X XOR Y (which is now (X XOR Y) XOR Y = X)
      Y := X xor Y;

      -- XOR swap step 3: X := X XOR Y (which is now (X XOR Y) XOR X = Y)
      X := X xor Y;
   end Swap_Using_XOR;

   -- Variables to be swapped
   A : Integer;
   B : Integer;

begin
