   Put("Enter first integer (A): ");
   Get(Item => A);

   -- Read the second integer
   Put("Enter second integer (B): ");
   Get(Item => B);

   -- Display the values before swapping
   Put_Line("Before swapping:");
   Put_Line("A = " & Integer'Image(A));
   Put_Line("B = " & Integer'Image(B));

   -- Call the swap procedure
   Swap_Using_XOR(A, B);

   -- Display the values after swapping
   Put_Line("After swapping:");
   Put_Line("A = " & Integer'Image(A));
   Put_Line("B = " & Integer'Image(B));

end XOR_Swap;
```

### Explanation of the XOR Swap Algorithm:
1. **Step 1**: `X := X xor Y`
