    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Prompt the user for the size of the array
        System.out.print("Enter the size of the array: ");
        int size = 0;

        try {
            size = Integer.parseInt(scanner.nextLine());
            if (size < 0) {
                System.out.println("Size cannot be negative. Exiting program.");
                return;
            }
        } catch (NumberFormatException e) {
            System.out.println("Invalid input for size. Please enter a valid integer. Exiting program.");
            return;
        }

        // Initialize the array
        int[] numbers = new int[size];

        // Prompt the user to enter each element of the array
        for (int i = 0; i < size; i++) {
            System.out.print("Enter element " + (i + 1) + ": ");
            try {
                numbers[i] = Integer.parseInt(scanner.nextLine());
            } catch (NumberFormatException e) {
                System.out.println("Invalid input. Please enter a valid integer. Exiting program.");
                return;
            }
        }

        // Calculate the sum of all odd numbers in the array
        int sumOfOdds = 0;
        for (int num : numbers) {
            if (num % 2 != 0) {
                sumOfOdds += num;
            }
        }

        // Output the sum of odd numbers
        System.out.println("The sum of all odd numbers in the array is: " + sumOfOdds);

        // Close the scanner
        scanner.close();
    }
}
