Creating a JavaScript program to generate random passwords with specified criteria is a practical application for learning about randomization, string manipulation, and user input. Below is an example of a simple password generator that prompts the user for the desired password length and whether to include special characters, numbers, and uppercase letters.

```javascript
function generatePassword() {
    // Prompt user for password criteria
    const length = parseInt(prompt("Enter desired password length (must be at least 4):"), 10);
    const includeSpecialChars = confirm("Include special characters?");
    const includeNumbers = confirm("Include numbers?");
    const includeUppercase = confirm("Include uppercase letters?");

    // Validate the length input
    if (isNaN(length) || length < 4) {
        alert("Password length must be a number and at least 4.");
        return;
    }

    // Character sets
    const lowercaseChars = "abcdefghijklmnopqrstuvwxyz";
    const uppercaseChars = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    const numberChars = "0123456789";
    const specialChars = "!@#$%^&*()_+[]{}|;:,.<>?";

    // Build the character pool based on user input
    let charPool = lowercaseChars;

    if (includeUppercase) {
        charPool += uppercaseChars;
    }
    if (includeNumbers) {
        charPool += numberChars;
    }
    if (includeSpecialChars) {
        charPool += specialChars;
    }

    // Ensure at least one character from each selected set is included
    let password = "";
    if (includeUppercase) {
        password += uppercaseChars[Math.floor(Math.random() * uppercaseChars.length)];
    }
    if (includeNumbers) {
        password += numberChars[Math.floor(Math.random() * numberChars.length)];
    }
    if (includeSpecialChars) {
        password += specialChars[Math.floor(Math.random() * specialChars.length)];
    }

    // Generate the rest of the password
    for (let i = password.length; i < length; i++) {
        const randomIndex = Math.floor(Math.random() * charPool.length);
        password += charPool[randomIndex];
    }

    // Shuffle the password to avoid predictable patterns
    password = password.split('').sort(() => Math.random() - 0.5).join('');

    return password;
}

// Generate and display a password
const newPassword = generatePassword();
if (newPassword) {
    console.log("Generated Password:", newPassword);
}
```

