<?php
/**
 * Function to perform bubble sort on an array
 *
 * @param array $array The array to be sorted
 * @param string $order The order of sorting ('asc' for ascending, 'desc' for descending)
 * @return array The sorted array
 */
function bubbleSort(array $array, string $order = 'asc'): array {
    $n = count($array);
    // Loop through each element of the array
    for ($i = 0; $i < $n - 1; $i++) {
        // Track if any swapping occurred
        $swapped = false;
        // Perform a pass through the array
        for ($j = 0; $j < $n - $i - 1; $j++) {
            // Compare adjacent elements based on the chosen order
            if (($order === 'asc' && $array[$j] > $array[$j + 1]) || 
                ($order === 'desc' && $array[$j] < $array[$j + 1])) {
                // Swap elements if they are in the wrong order
                $temp = $array[$j];
                $array[$j] = $array[$j + 1];
                $array[$j + 1] = $temp;
                $swapped = true;
            }
        }
        // If no two elements were swapped, the array is sorted
        if (!$swapped) {
            break;
        }
    }
    return $array;
}

