Below is a C program that prompts the user to enter the first term, the common difference, and the value of N for an arithmetic progression. It calculates the sum of the first N terms using the given formula and includes error handling for non-numeric inputs and negative values of N.

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

// Function to check if a string is a valid integer
bool isValidInteger(char *str) {
    if (*str == '-' || *str == '+') {
        str++;
    }
    if (*str == '\0') {
        return false; // empty string or only a sign
    }
    while (*str) {
        if (*str < '0' || *str > '9') {
            return false;
        }
        str++;
    }
    return true;
}

// Main function
int main() {
    char input[100];
    int a, d, N;

    // Prompt user for the first term
    printf("Enter the first term (a) of the arithmetic progression: ");
    scanf("%s", input);
    if (!isValidInteger(input)) {
        printf("Invalid input. Please enter a numeric value.\n");
        return 1;
    }
    a = atoi(input);

    // Prompt user for the common difference
    printf("Enter the common difference (d) of the arithmetic progression: ");
    scanf("%s", input);
    if (!isValidInteger(input)) {
        printf("Invalid input. Please enter a numeric value.\n");
        return 1;
    }
    d = atoi(input);

    // Prompt user for the number of terms
    printf("Enter the number of terms (N): ");
    scanf("%s", input);
    if (!isValidInteger(input) || (N = atoi(input)) < 0) {
        printf("Invalid input. N must be a non-negative integer.\n");
        return 1;
    }

    // Calculate the sum of the first N terms
    long sum = (N / 2.0) * (2 * a + (N - 1) * d);

    // Display the result
    printf("The sum of the first %d terms of the arithmetic progression is: %ld\n", N, sum);

    return 0;
}
```

### Explanation

1. **Input Validation**: The `isValidInteger` function checks if the input string is a valid integer. It allows for an optional sign (`+` or `-`) at the beginning.

2. **User Input**: The program prompts the user to enter the first term, the common difference, and the number of terms, storing each input as a string to validate it before converting it to an integer.

3. **Error Handling**: If the input is not a valid integer or if N is negative, the program displays an error message and exits.

