    for ($i = 0; $i < strlen($message); $i++) {
        $char = $message[$i];

        if (ctype_alpha($char)) {
            $asciiOffset = ctype_upper($char) ? ord('A') : ord('a');
            $encryptedChar = chr((ord($char) + $shift - $asciiOffset) % 26 + $asciiOffset);
            $result .= $encryptedChar;
