### Step 3: Create the Custom Directive

Add the custom directive to your module. This directive will manage the input field, character counting, and error message.

```javascript
angular.module('myApp').directive('customInput', function() {
  return {
    restrict: 'E',
    scope: {
      maxChars: '@'
    },
    template: `
      <input type="text" ng-model="userInput" ng-change="updateCount()" />
      <div class="character-count">
        {{ remainingChars }} characters remaining
      </div>
      <div class="error" ng-show="exceeded">
        Maximum character limit exceeded!
      </div>
    `,
    link: function(scope) {
      scope.userInput = '';
      scope.remainingChars = scope.maxChars;
      scope.exceeded = false;

      scope.updateCount = function() {
        const inputLength = scope.userInput.length;
        scope.remainingChars = scope.maxChars - inputLength;
        scope.exceeded = inputLength > scope.maxChars;
      };
    }
  };
});
```

### Explanation:

- **Directive Definition**: The directive is defined with `restrict: 'E'`, meaning it can be used as an element. It takes a `maxChars` attribute to specify the maximum number of characters allowed
